package com.unicare.dispensary.config;
import java.util.Map;import java.util.stream.Collectors;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.ExceptionHandler;import org.springframework.web.bind.annotation.RestControllerAdvice;import org.springframework.web.server.ResponseStatusException;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(MethodArgumentNotValidException.class)public ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException ex){var errors=ex.getBindingResult().getFieldErrors().stream().collect(Collectors.toMap(e->e.getField(),e->e.getDefaultMessage(),(a,b)->a));return ResponseEntity.badRequest().body(Map.of("message","Please correct the highlighted fields.","errors",errors));}@ExceptionHandler(ResponseStatusException.class)public ResponseEntity<Map<String,String>> status(ResponseStatusException ex){return ResponseEntity.status(ex.getStatusCode()).body(Map.of("message",ex.getReason()==null?"Request failed.":ex.getReason()));}@ExceptionHandler(Exception.class)public ResponseEntity<Map<String,String>> unexpected(Exception ex){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("message","An unexpected server error occurred."));}}
